const collections = [
 {id:'jackfruit',name:'Jackfruit',group:'tree',subtitle:'A world within one fruit',color:'#e8edda',description:'Discover the possibilities of jackfruit through our value-added product range. Explore this distinctive ingredient with NATIVE NATURE.'},
 {id:'banana',name:'Banana tree',group:'tree',subtitle:'Beyond the everyday banana',color:'#f0ead3',description:'An ingredient family with a remarkable story. Explore our banana-tree product collection and ask about the range currently available.'},
 {id:'groundnut',name:'Groundnut',group:'field',subtitle:'Small nut. Plenty of possibility.',color:'#eee1d3',description:'A familiar favourite with many possibilities. Discover groundnut products from Senthoor Foods India and discuss your requirements.'},
 {id:'cashew',name:'Cashew',group:'tree',subtitle:'An enduring favourite',color:'#ede9df',description:'Explore our cashew collection, from everyday needs to business requirements. Ask us about available formats and quantities.'},
 {id:'fruits',name:'Fruits',group:'tree',subtitle:'Nature’s colourful collection',color:'#efe3d4',description:'Discover our fruit-based product range. Enquire to learn which fruits and product formats are currently available.'},
 {id:'rice',name:'Rice',group:'field',subtitle:'At the heart of the everyday',color:'#e8e8d8',description:'An everyday staple, part of the NATIVE NATURE collection. Tell us about the rice products and quantities you are looking for.'},
 {id:'seafood',name:'Seafood',group:'coast',subtitle:'Possibilities from the coast',color:'#dfe9e6',description:'Explore the seafood side of our range. Contact Senthoor Foods India for current products, availability and handling information.'}
];
const grid = document.querySelector('#collection-grid');
function renderCollections(filter='all') {
 grid.innerHTML = collections.filter(c=>filter==='all'||c.group===filter).map(c=>`<article class="collection-card"><button data-open="${c.id}" aria-label="Explore ${c.name} collection"><div class="card-art" style="--card-bg:${c.color}"><span class="card-count">${String(collections.indexOf(c)+1).padStart(2,'0')} / COLLECTION</span>${art[c.id]}</div><div class="card-bottom"><div><h3>${c.name}</h3><p>${c.subtitle}</p></div><span class="card-arrow" aria-hidden="true">↗</span></div></button></article>`).join('');
}
renderCollections();
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{
 document.querySelectorAll('[data-filter]').forEach(b=>{const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});renderCollections(button.dataset.filter);
}));
const dialog=document.querySelector('#collection-dialog');let selectedCollection=null;
document.addEventListener('click',event=>{const button=event.target.closest('[data-open]');if(!button)return;selectedCollection=collections.find(c=>c.id===button.dataset.open);document.querySelector('#dialog-title').textContent=selectedCollection.name;document.querySelector('#dialog-origin').textContent=`FROM THE ${selectedCollection.group.toUpperCase()} / THE COLLECTION`;document.querySelector('#dialog-art').innerHTML=art[selectedCollection.id];document.querySelector('#dialog-art').style.background=selectedCollection.color;document.querySelector('#dialog-description').textContent=selectedCollection.description;dialog.showModal();document.body.classList.add('modal-open');});
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('close',()=>document.body.classList.remove('modal-open'));
dialog.addEventListener('click',event=>{const rect=dialog.getBoundingClientRect();if(event.target===dialog&&(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom))dialog.close();});
document.querySelector('#dialog-enquire').addEventListener('click',()=>{document.querySelector('#enquiry-collection').value=selectedCollection.name;dialog.close();document.querySelector('#contact').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});document.querySelector('[name="name"]').focus({preventScroll:true});});
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#navigation');
function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');}
menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();}});
document.querySelector('#year').textContent=new Date().getFullYear();
document.querySelector('#enquiry-form').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);const text=`NATIVE NATURE — Enquiry for Senthoor Foods India\n\nName: ${data.get('name')}\nEmail: ${data.get('email')}\nCompany: ${data.get('company')||'Not specified'}\nCollection: ${data.get('collection')}\n\nRequirement:\n${data.get('message')}\n\nThis enquiry has been prepared locally and has not been sent.\n`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='native-nature-enquiry.txt';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#form-status').textContent='Your enquiry file is ready. Share the downloaded file with Senthoor Foods India; it has not been sent online.';});
